      this._photos=(result.photos||[]).filter(p=>{try{const u=new URL(p.url);return u.protocol==='https:'&&u.hostname.endsWith('.icloud-content.com');}catch{return false;}});
      this._lastPhotos=Date.now();this._photoQueue=[];
