    if(!this._photoQueue?.length){this._photoQueue=[...this._photos];for(let i=this._photoQueue.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[this._photoQueue[i],this._photoQueue[j]]=[this._photoQueue[j],this._photoQueue[i]];}if(this._photoQueue.length>1&&this._photoQueue.at(-1).id===this._currentPhoto)this._photoQueue.unshift(this._photoQueue.pop());}
    const photo=this._photoQueue.pop(),index=1-this._activePhotoLayer,img=this._photoLayers[index];img.classList.remove('visible');
    const loaded=await new Promise(resolve=>{const finish=ok=>{clearTimeout(timer);img.onload=null;img.onerror=null;resolve(ok);};const timer=setTimeout(()=>finish(false),20000);img.onload=()=>finish(true);img.onerror=()=>finish(false);img.src=photo.url;});
