  async _loadTodo(){if(!this._hass||this._todoLoading)return;this._todoLoading=true;try{const r=await this._hass.callWS({type:'call_service',domain:'todo',service:'get_items',target:{entity_id:this._config.todo_entity},service_data:{},return_response:true});this._items=r.response?.[this._config.todo_entity]?.items||[];this._renderTodo();}catch(e){this.shadowRoot.querySelector('.tasks').textContent='Tasks are temporarily unavailable.';}finally{this._todoLoading=false;}}
